// flashcard drill — JAH Vitamins and Minerals Database (jahdb demo program)
var ITEMS=[["Vitamin A","Vision, immunity, skin. Sources: liver, carrots, sweet potato. Deficiency: night blindness."], ["Vitamin B1 (thiamine)","Energy metabolism, nerves. Sources: whole grains, pork. Deficiency: beriberi."], ["Vitamin B2 (riboflavin)","Energy release, skin, eyes. Sources: dairy, eggs. Deficiency: cracks at mouth corners."], ["Vitamin B3 (niacin)","DNA repair, metabolism. Sources: meat, peanuts. Deficiency: pellagra."], ["Vitamin B5 (pantothenic acid)","Coenzyme A, energy. Sources: almost all foods. Deficiency: very rare."], ["Vitamin B6 (pyridoxine)","Amino acid metabolism, brain. Sources: poultry, bananas. Deficiency: anemia, confusion."], ["Vitamin B7 (biotin)","Fat and protein metabolism, hair, nails. Sources: eggs, nuts. Deficiency: rare."], ["Vitamin B9 (folate)","Cell division, pregnancy. Sources: leafy greens, legumes. Deficiency: neural tube defects."], ["Vitamin B12 (cobalamin)","Nerves, red blood cells. Sources: animal foods. Deficiency: pernicious anemia."], ["Vitamin C","Collagen, immunity, iron absorption. Sources: citrus, peppers. Deficiency: scurvy."], ["Vitamin D","Calcium absorption, bones, immunity. Sources: sun, fatty fish. Deficiency: rickets."], ["Vitamin E","Antioxidant, cell membranes. Sources: nuts, seeds, oils. Deficiency: rare nerve issues."], ["Vitamin K","Blood clotting, bones. Sources: leafy greens, gut bacteria. Deficiency: bleeding."], ["Calcium","Bones, teeth, muscle signals. Sources: dairy, greens. About 1,000 mg/day."], ["Iron","Hemoglobin oxygen transport. Sources: red meat, lentils. Deficiency: anemia."], ["Magnesium","300+ enzyme reactions, muscles, sleep. Sources: nuts, greens. About 400 mg/day."], ["Potassium","Fluid balance, blood pressure, heart. Sources: bananas, potatoes. About 3,500 mg/day."], ["Sodium","Fluid balance, nerves. Needed in small amounts; excess raises blood pressure."], ["Chloride","Stomach acid, fluid balance. Comes with sodium in salt."], ["Zinc","Immunity, wound healing, taste. Sources: 